void dei_ss_full_silent_arm( void *remote )
{
  if((ss_system_type & SYS_TYPE_SS) != SYS_TYPE_SS)
    return;
  
	if( !get_ss_valet() )
		dei_ss_arm_cmd = DEI_SS_FULL_SILENT_ARM;

	cmd_q_rs_insert( INPUT_RF_SILENT_LOCK, 100 );

	os_tsk_wait(100);
	if( !get_ss_valet() )
	{
		set_ss_sensor_silent_arm( FALSE );
		set_ss_full_silent_arm( TRUE );
		dei_ss_arm_cmd = DEI_SS_ARM_NONE;

		notify_send( NOTIFY_FULL_SILENT_ARM ) ; 
			
		dei_siren_chirp( DEI_SIREN_FULL_SILENT_ARM ); 
		//dei_prk_flash  ( DEI_PRK_FULL_SILENT_ARM   ); // Removed to fix bug #5106
	}

}


